Lemma nretA_MSsvc_w : forall R F pc x8 fc rv m ro r ws,
  nretA (MSsvc R F pc x8 fc rv m ro) (mkEffect r ws []) = MS (bvmap_set 10 r R) F (pc + Z_to_bv 64 4)%bv fc rv
    (apply_writes (apply_zeros (apply_unmaps m []) []) ws) ro.
Proof.
